if (points.size() <= 1) return points;

std::vector<Point2d> pts = points;
std::sort(pts.begin(), pts.end(),
    [](const Point2d& a, const Point2d& b) {
        if (a.x != b.x) return a.x < b.x;
        return a.y < b.y;
    });
pts.erase(std::unique(pts.begin(), pts.end(),
    [](const Point2d& a, const Point2d& b) {
        return a.x == b.x && a.y == b.y;
    }), pts.end());

if (pts.size() <= 2) return pts;

auto cross = [](const Point2d& O, const Point2d& A, const Point2d& B) {
    return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
};

std::vector<Point2d> lower;
for (const auto& p : pts) {
    while (lower.size() >= 2 &&
           cross(lower[lower.size() - 2], lower[lower.size() - 1], p) <= 0) {
        lower.pop_back();
    }
    lower.push_back(p);
}

std::vector<Point2d> upper;
for (auto it = pts.rbegin(); it != pts.rend(); ++it) {
    const auto& p = *it;
    while (upper.size() >= 2 &&
           cross(upper[upper.size() - 2], upper[upper.size() - 1], p) <= 0) {
        upper.pop_back();
    }
    upper.push_back(p);
}

lower.pop_back();
upper.pop_back();
lower.insert(lower.end(), upper.begin(), upper.end());
return lower;

